if (!route_locks.empty()) {
  std::string joined_locks;
  for (const auto& lock_id : route_locks) {
    if (!joined_locks.empty()) {
      joined_locks += ",";
    }
    joined_locks += lock_id;
  }
  m.reservation_id = joined_locks;
}

