  amr_dispatcher_interfaces::msg::MissionEvent msg;
  msg.stamp = now();
  msg.mission_id = m.id;
  msg.order_id = m.order_id;
  msg.event = "active";
  msg.from_state = "PENDING";
  msg.to_state = "ACTIVE";
  msg.reason = "dispatched by scheduler";
  event_pub_->publish(msg);
}

