   */
  virtual std::vector<Pose2D> Plan(const Pose2D& start, const Pose2D& goal,
                                   const std::string& edge_id = "") = 0;

  /**
   * @brief 获取规划器实现名称
   */
  virtual std::string GetPlannerName() const = 0;
};

