  amr_dispatcher_core::dispatcher::Mission m = *pop.mission;
  dispatch_counters_.dispatch_total++;
  m.state = amr_dispatcher_core::dispatcher::MissionState::kActive;
  m.assigned_vehicle_id = dispatch_vehicle_id;  // 落定承接车辆（审计用）
